    if(path==="/self-improvement-v3" && method==="GET")return new Response("<!doctype html><html lang=\"it\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#07101f\"><title>JARVIS · Self-Improvement v3</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#07101f;color:#e6f3ff;font:15px system-ui,sans-serif}main{max-width:760px;margin:auto;padding:24px 16px 75px}h1{font-size:26px;margin:16px 0}h2{font-size:18px}p{color:#aabfd8;line-height:1.5}.panel{background:#122035;border:1px solid #2c4d6d;border-radius:15px;padding:18px;margin:14px 0}.button{padding:11px 13px;border-radius:10px;border:1px solid #4183ad;background:#17405e;color:#edf7ff;font:inherit;cursor:pointer;margin:4px 5px 4px 0}.secondary{background:transparent}.button:disabled{opacity:.5}select{width:100%;border-radius:10px;border:1px solid #42668a;background:#071929;color:#edf7ff;padding:12px;font:inherit}a{color:#95d7fa}label{font-weight:650;display:block;margin-bottom:8px}.muted,small{color:#a8bfd9}.result{border-top:1px solid #345471;padding:13px 0}.title{font-weight:650}.tag{display:inline-block;border:1px solid #4a6d88;border-radius:20px;padding:3px 9px;font-size:12px}#status{white-space:pre-wrap;overflow-wrap:anywhere}button:focus-visible{outline:2px solid #8ed7ff}</style></head><body><main><a href=\"/executor-v3\">← Executor</a><h1>JARVIS · Self-Improvement</h1><p>Analizza le anomalie individuate dall'Executor e prepara proposte verificabili. Non modifica il codice o i dati del progetto.</p><section class=\"panel\"><label for=\"project\">Progetto</label><select id=\"project\"><option value=\"\">Caricamento…</option></select><p><small>Se necessario, JARVIS esegue automaticamente la diagnostica Executor in sola lettura. Se tutti i controlli sono superati, non viene inventato alcun problema.</small></p><button class=\"button\" id=\"prepare\">Prepara proposte dalle anomalie</button><button class=\"button secondary\" id=\"refresh\">Aggiorna</button><p id=\"status\" role=\"status\"></p></section><section class=\"panel\"><h2>Proposte di intervento</h2><div id=\"proposals\" class=\"muted\">Caricamento…</div></section><p><small>L'approvazione di una proposta autorizza soltanto la preparazione di successivi test isolati. Non attiva modifiche, deploy, ripristini o spese. Ogni modifica futura richiederà ulteriore approvazione.</small></p></main><script>const el=id=>document.getElementById(id);async function api(path,options){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('Risposta inattesa (HTTP '+r.status+')');const d=await r.json();if(!r.ok)throw Error(d.error||'HTTP '+r.status);return d}function message(t){el('status').textContent=t}async function loadProjects(){try{const data=await api('/api/projects');const select=el('project');select.replaceChildren();for(const p of (data.projects||[]).filter(x=>x.status==='active')){const opt=document.createElement('option');opt.value=p.id;opt.textContent=p.name;select.append(opt)}const j=[...select.options].find(x=>x.textContent.toLowerCase()==='jarvis');if(j)select.value=j.value;await load()}catch(e){message('Progetti non disponibili: '+e.message)}}async function load(){const project_id=el('project').value;if(!project_id)return;try{const data=await api('/api/self-improvement/proposals?project_id='+encodeURIComponent(project_id));const box=el('proposals');box.replaceChildren();if(!data.proposals.length){box.textContent='Nessuna anomalia trasformata in proposta. I controlli risultano puliti oppure non hai ancora preparato le proposte.';return}for(const p of data.proposals){const item=document.createElement('article');item.className='result';const title=document.createElement('div');title.className='title';title.textContent=p.title;const tag=document.createElement('span');tag.className='tag';tag.textContent=p.status+' · rischio '+p.risk;item.append(title,tag);for(const [label,key] of [['Diagnosi','diagnosis'],['Intervento proposto','suggested_change'],['Piano di verifica','test_plan'],['Piano di rollback','rollback_plan']]){const detail=document.createElement('p');detail.textContent=label+': '+String(p[key]||'');item.append(detail)}if(p.status==='draft'){for(const [action,label] of [['approve-review','Approva preparazione'],['reject','Rifiuta']]){const button=document.createElement('button');button.className='button'+(action==='reject'?' secondary':'');button.textContent=label;button.addEventListener('click',async()=>{if(action==='approve-review'&&!window.confirm('Approvi solo la preparazione di test futuri? Nessuna modifica verrà applicata.'))return;button.disabled=true;try{await api('/api/self-improvement/proposals/'+encodeURIComponent(p.id)+'/'+action,{method:'POST'});message(action==='approve-review'?'Autorizzata preparazione futura, nessuna modifica eseguita.':'Proposta rifiutata.');await load()}catch(e){message('Operazione non riuscita: '+e.message);button.disabled=false}});item.append(button)}}box.append(item)}}catch(e){message('Errore lettura proposte: '+e.message)}}el('prepare').addEventListener('click',async()=>{const id=el('project').value;if(!id)return;const button=el('prepare');button.disabled=true;message('Analizzo gli ultimi risultati Executor…');try{const runs=await api('/api/executor/runs?project_id='+encodeURIComponent(id));if(!(runs.runs||[]).some(r=>r.status==='completed')){message('Nessun controllo precedente: eseguo i cinque controlli Executor, senza modificare il progetto…');const result=await api('/api/executor/run',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:id})});if(result.status==='already_requested'){const prior=await api('/api/executor/runs/'+encodeURIComponent(result.run_id));if(prior.run?.status!=='completed')throw Error('Diagnostica già avviata ma non completata');}else if(result.status!=='completed')throw Error('Diagnostica incompleta');}message('Verifica completata. Controllo le proposte…');const result=await api('/api/self-improvement/prepare',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:id})});message(result.warnings===0?'Ultima diagnostica senza anomalie: nessuna correzione necessaria.':'Anomalie: '+result.warnings+' · Nuove proposte: '+result.generated+'. Nessuna modifica applicata.');await load()}catch(e){message('Preparazione non riuscita: '+e.message)}finally{button.disabled=false}});el('refresh').addEventListener('click',load);el('project').addEventListener('change',load);loadProjects();</script></body></html>",{headers:{"Content-Type":"text/html; charset=utf-8","Cache-Control":"no-store","X-Content-Type-Options":"nosniff","Content-Security-Policy":"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"}});
if(path==='/sandbox-v3'&&method==='GET')return new Response("<!doctype html><html lang=\"it\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#07101f\"><title>JARVIS · Sandbox v3</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#07101f;color:#e9f3ff;font:15px system-ui,sans-serif}main{max-width:760px;margin:auto;padding:22px 16px 70px}h1{font-size:27px;margin:16px 0}h2{font-size:19px}p{color:#afc4d9;line-height:1.5}a{color:#91d7ff}.panel{padding:18px;margin:15px 0;border:1px solid #2b4d6f;border-radius:16px;background:#102036}label{display:block;font-weight:600;margin:12px 0 8px}select{width:100%;padding:12px;border-radius:10px;border:1px solid #416386;background:#091729;color:#e8f5ff;font:inherit}button{padding:11px 13px;margin:5px 7px 5px 0;background:#174363;color:#eaf5ff;border-radius:10px;border:1px solid #4b8cb9;font:inherit;cursor:pointer}button.secondary{background:transparent}button:disabled{opacity:.55}.item{padding:14px 0;border-top:1px solid #365574}.title{font-weight:650}.tag{display:inline-block;font-size:12px;padding:3px 8px;border-radius:20px;border:1px solid #527490;margin-bottom:6px}.pass{color:#9de4be}.warn{color:#f5d19b}.muted,small{color:#a9bfd6}#status{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><main><a href=\"/self-improvement-v3\">← Self-Improvement</a><h1>Sandbox · Auto-Correction</h1><p>Prove ripetibili su dati sintetici: confronto prima/dopo, verifica di ripristino e blocco dei cambiamenti che richiedono giudizio. Non sono test del codice Worker, né un rollback reale.</p><section class=\"panel\"><label for=\"project\">Progetto</label><select id=\"project\"><option value=\"\">Caricamento…</option></select><button id=\"run\">Esegui test sintetici</button><button class=\"secondary\" id=\"refresh\">Aggiorna storico</button><p id=\"status\" role=\"status\">Nessun test avviato.</p></section><section class=\"panel\"><h2>Risultati</h2><div id=\"results\" class=\"muted\">Nessun risultato in questa sessione.</div></section><section class=\"panel\"><h2>Storico</h2><div id=\"history\" class=\"muted\">Caricamento…</div></section><p><small>La sandbox simula correzioni in memoria su copie di dati fittizi. Non esegue patch a progetti, codice o database reali. Un ambiente Worker separato e un ripristino di versione restano da implementare.</small></p></main><script>const el=id=>document.getElementById(id);async function api(path,options){const r=await fetch(path,{credentials:'same-origin',cache:'no-store',...options});if(!(r.headers.get('content-type')||'').includes('application/json'))throw Error('Risposta non JSON, HTTP '+r.status);const d=await r.json();if(!r.ok)throw Error(d.error||'HTTP '+r.status);return d}function render(report){const box=el('results');box.replaceChildren();const summary=document.createElement('p');summary.textContent=report.passed+'/'+report.total+' test superati · ambiente: dati sintetici';box.append(summary);for(const x of report.results||[]){const item=document.createElement('div');item.className='item';const tag=document.createElement('span');tag.className='tag '+(x.passed?'pass':'warn');tag.textContent=x.passed?'Superato':'Non superato';const title=document.createElement('div');title.className='title';title.textContent=x.title;const metrics=document.createElement('p');metrics.textContent='Anomalie prima: '+x.issues_before+' · dopo: '+x.issues_after+' · rollback simulato: '+(x.rollback_from_snapshot_verified?'OK':'errore');const detail=document.createElement('p');detail.textContent=x.action;item.append(tag,title,metrics,detail);box.append(item)}}async function loadProjects(){try{const data=await api('/api/projects');const s=el('project');s.replaceChildren();for(const p of(data.projects||[]).filter(x=>x.status==='active')){const o=document.createElement('option');o.value=p.id;o.textContent=p.name;s.append(o)}const j=[...s.options].find(x=>x.textContent.toLowerCase()==='jarvis');if(j)s.value=j.value;await history()}catch(e){el('status').textContent='Progetti non disponibili: '+e.message}}async function history(){const id=el('project').value;if(!id)return;const box=el('history');try{const d=await api('/api/sandbox/runs?project_id='+encodeURIComponent(id));box.replaceChildren();if(!d.runs?.length){box.textContent='Nessun test sintetico eseguito per questo progetto.';return}for(const r of d.runs){const row=document.createElement('div');row.className='item';const t=document.createElement('div');t.textContent=r.created_at+' · '+r.passed+'/'+r.total+' superati';const b=document.createElement('button');b.className='secondary';b.textContent='Apri';b.addEventListener('click',()=>openRun(r.id));row.append(t,b);box.append(row)}}catch(e){box.textContent='Storico non disponibile: '+e.message}}async function openRun(id){try{const d=await api('/api/sandbox/runs/'+encodeURIComponent(id));render(d.report);el('status').textContent='Risultato salvato, nessuna modifica alla produzione.'}catch(e){el('status').textContent='Lettura risultato fallita: '+e.message}}el('run').addEventListener('click',async()=>{const id=el('project').value;if(!id)return;const button=el('run');button.disabled=true;el('status').textContent='Eseguo le prove sintetiche…';try{const d=await api('/api/sandbox/test',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({project_id:id})});if(d.report)render(d.report);else if(d.run_id)await openRun(d.run_id);el('status').textContent=d.status==='already_tested'?'Test già registrato nell’ultimo minuto.':'Suite completata: '+d.report.passed+'/'+d.report.total+' test superati. Nessuna modifica applicata.';await history()}catch(e){el('status').textContent='Errore test: '+e.message}finally{button.disabled=false}});el('refresh').addEventListener('click',history);el('project').addEventListener('change',history);loadProjects();</script></body></html>",{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"}});
