if(path==='/recovery-download-v3'&&method==='GET')return new Response("<!doctype html><html lang=\"it\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#07101f\"><title>JARVIS · Backup cifrato</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#07101f;color:#e9f5ff;font:15px system-ui,sans-serif}main{max-width:720px;margin:auto;padding:25px 16px 65px}h1{font-size:26px}p{color:#b1c5db;line-height:1.55}.card{background:#102037;border:1px solid #2e4c6a;border-radius:15px;padding:17px;margin:16px 0}label{display:block;font-weight:600;margin:12px 0 6px}input{width:100%;background:#071321;color:#e9f5ff;padding:12px;border:1px solid #436587;border-radius:10px;font:inherit}button{background:#1b4c70;border:1px solid #5492c0;border-radius:10px;padding:12px 15px;color:#f1f8ff;font:inherit;cursor:pointer;margin-top:12px}button:disabled{opacity:.5}a{color:#a6dfff}#status,#checkStatus{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#9caec5}</style></head><body><main><a href=\"/staging-control-v3\">← Staging Control</a><h1>JARVIS · Archivio cifrato</h1><p>Scarica una copia verificata dei dati di JARVIS e cifrala direttamente sul tuo Android. La password rimane soltanto nel browser: non viene inviata a Cloudflare o a ChatGPT.</p><div class=\"card\"><h2>Stato della copia</h2><p id=\"snapshotState\" role=\"status\">Controllo aggiornamento backup…</p><small>Una copia verificata può non includere le modifiche più recenti. Il file non esiste fuori da Cloudflare finché non viene effettivamente salvato sul dispositivo.</small></div><div class=\"card\"><h2>Crea copia AES-256-GCM</h2><label for=\"pass\">Password di cifratura (almeno 12 caratteri)</label><input id=\"pass\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\"><label for=\"confirm\">Ripeti password</label><input id=\"confirm\" type=\"password\" autocomplete=\"new-password\" minlength=\"12\"><button id=\"save\">Verifica, cifra e salva backup</button><p id=\"status\" role=\"status\">Pronto. La copia rimarrà cifrata sul dispositivo.</p><small>Conserva la password in un luogo separato dall'archivio. Se la perdi, non sarà possibile decifrare la copia.</small></div><div class=\"card\"><h2>Verifica backup scaricato</h2><label for=\"file\">Seleziona un file .jarvisbak</label><input id=\"file\" type=\"file\" accept=\".jarvisbak,application/json\"><label for=\"restorePass\">Password del backup</label><input id=\"restorePass\" type=\"password\" autocomplete=\"off\"><button id=\"verify\">Verifica localmente il file</button><p id=\"checkStatus\" role=\"status\">Nessun file verificato.</p><small>La verifica legge il file localmente. Non carica dati nel server e non modifica il database reale.</small></div><p><small>La copia è salvata nell'account Cloudflare finché non la scarichi sul tuo dispositivo. Questo strumento non sostituisce una strategia di backup esterna con più copie indipendenti.</small></p></main><script>const el=id=>document.getElementById(id),enc=new TextEncoder(),dec=new TextDecoder();function b64(bytes){let out='';for(let i=0;i<bytes.length;i+=8192)out+=String.fromCharCode(...bytes.subarray(i,i+8192));return btoa(out)}function from64(str){const raw=atob(str);return Uint8Array.from(raw,c=>c.charCodeAt(0))}async function digest(bytes){const hash=new Uint8Array(await crypto.subtle.digest('SHA-256',bytes));return b64(hash)}async function derive(password,salt){const base=await crypto.subtle.importKey('raw',enc.encode(password),'PBKDF2',false,['deriveKey']);return crypto.subtle.deriveKey({name:'PBKDF2',salt,iterations:310000,hash:'SHA-256'},base,{name:'AES-GCM',length:256},false,['encrypt','decrypt'])}el('save').addEventListener('click',async()=>{const button=el('save'),status=el('status'),password=el('pass').value;if(password.length<12||password!==el('confirm').value){status.textContent='Imposta due password identiche di almeno 12 caratteri.';return}button.disabled=true;try{status.textContent='Recupero lo snapshot verificato dal servizio privato…';const res=await fetch('/api/recovery/backup-download',{method:'POST',credentials:'same-origin',headers:{'x-jarvis-export-intent':'encrypt-locally'}});if(!res.ok)throw Error('Accesso al backup non riuscito (HTTP '+res.status+')');const payload=await res.text();const parsed=JSON.parse(payload);if(parsed.format!=='JARVIS_VERIFIED_D1_BACKUP_V1'||!parsed.metadata?.verified||!Array.isArray(parsed.schema)||parsed.schema.filter(x=>x.object_type==='table').length!==parsed.metadata.table_count||parsed.rows?.length!==parsed.metadata.rows_total)throw Error('Snapshot non coerente');status.textContent='Cifro la copia nel browser, senza inviare la password…';const bytes=enc.encode(payload),salt=crypto.getRandomValues(new Uint8Array(16)),iv=crypto.getRandomValues(new Uint8Array(12)),key=await derive(password,salt);const ciphertext=new Uint8Array(await crypto.subtle.encrypt({name:'AES-GCM',iv},key,bytes));const plain=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv},key,ciphertext));if(await digest(bytes)!==await digest(plain))throw Error('La verifica crittografica non è riuscita');const envelope={format:'JARVIS_AES256_GCM_BACKUP_V1',kdf:'PBKDF2_SHA256',iterations:310000,salt:b64(salt),iv:b64(iv),ciphertext:b64(ciphertext),plaintext_sha256:b64(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))),snapshot_id:parsed.metadata.id};const blob=new Blob([JSON.stringify(envelope)],{type:'application/octet-stream'});const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='jarvis-backup-'+parsed.metadata.id+'.jarvisbak';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);status.textContent='Backup cifrato e verificato. Il browser ha avviato il salvataggio di '+parsed.metadata.table_count+' tabelle e '+parsed.metadata.rows_total+' record. Conserva la password separatamente.';el('pass').value='';el('confirm').value=''}catch(e){status.textContent='Backup non completato: '+String(e.message||e).slice(0,240)}finally{button.disabled=false}});el('verify').addEventListener('click',async()=>{const file=el('file').files?.[0],pwd=el('restorePass').value,out=el('checkStatus');if(!file||!pwd){out.textContent='Seleziona il backup e inserisci la password.';return}el('verify').disabled=true;try{const envelope=JSON.parse(await file.text());if(envelope.format!=='JARVIS_AES256_GCM_BACKUP_V1'||envelope.iterations!==310000)throw Error('Formato non riconosciuto');const key=await derive(pwd,from64(envelope.salt));const plain=new Uint8Array(await crypto.subtle.decrypt({name:'AES-GCM',iv:from64(envelope.iv)},key,from64(envelope.ciphertext)));if(await digest(plain)!==envelope.plaintext_sha256)throw Error('Impronta del contenuto non valida');const data=JSON.parse(dec.decode(plain));if(!Array.isArray(data.schema)||data.schema.filter(x=>x.object_type==='table').length!==data.metadata?.table_count||data.rows?.length!==data.metadata?.rows_total)throw Error('Record non coerenti');out.textContent='Backup verificato localmente: '+data.metadata.table_count+' tabelle, '+data.metadata.rows_total+' record. Nessun dato inviato. Nessun ripristino eseguito.'}catch(e){out.textContent='Impossibile verificare: password errata o archivio non valido.'}finally{el('verify').disabled=false}});async function updateSnapshotStatus(){const p=el('snapshotState');try{const response=await fetch('/api/recovery/backup-service-status',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('Controllo non disponibile');const d=await response.json();if(d.status!=='verified'||!d.hash_checks_passed)throw Error('Copia non verificata');const date=d.snapshot_created_at||'non disponibile';p.textContent='Backup verificato: '+d.tables+' tabelle, '+d.rows+' record · creato il '+date+'. '+(d.stale_or_changed?'ATTENZIONE: il database corrente contiene '+d.live_tables+' tabelle e '+d.live_rows+' record; questa copia è precedente alle ultime modifiche.':'Il numero di tabelle e record coincide con il database attuale (non è un confronto completo dei contenuti).')}catch(e){p.textContent='Non riesco a verificare quanto sia recente la copia: '+String(e.message||e)}}updateSnapshotStatus();</script></body></html>",{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"}});
