if(path==='/api/recovery/backup-service-status'&&method==='GET'){
 if(!env.BACKUP_SERVICE)return json({status:'unavailable'},503,origin);
 try{const r=await env.BACKUP_SERVICE.fetch('https://jarvis-backup.internal/verified-snapshot',{method:'GET',signal:AbortSignal.timeout(12000)});if(!r.ok)return json({status:'unavailable',reason:'Internal verification failure'},503,origin);const d=await r.json();const tableRows=env.DB?(await env.DB.prepare("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' AND name NOT LIKE '_cf_%' ORDER BY name").all()).results||[]:[];const tableNames=tableRows.map(x=>x.name).filter(x=>/^[A-Za-z_][A-Za-z0-9_]*$/.test(x));let liveRowCount=null;if(env.DB&&tableNames.length){liveRowCount=0;for(let i=0;i<tableNames.length;i+=12){const sql='SELECT '+tableNames.slice(i,i+12).map(x=>'(SELECT count(*) FROM '+x+')').join('+')+' AS n';const tally=await env.DB.prepare(sql).first();liveRowCount+=tally?.n||0}};const latestTableCount=tableNames.length;const matchesCounts=latestTableCount===d.metadata?.table_count&&liveRowCount===d.metadata?.rows_total;return json({status:'verified',snapshot_id:d.metadata?.id,snapshot_created_at:d.metadata?.created_at||null,tables:d.metadata?.table_count,rows:d.metadata?.rows_total,live_tables:latestTableCount,live_rows:liveRowCount,appears_current_by_counts:matchesCounts,stale_or_changed:!matchesCounts,hash_checks_passed:d.metadata?.verified===true,download_requires_access:true,plain_backup_public:false,off_cloudflare_copy_exists:false},200,origin)}catch{return json({status:'unavailable'},503,origin)}
}
if(path==='/autonomy-control-v3'&&method==='GET')return new Response("<!doctype html><html lang=\"it\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#07101f\"><title>JARVIS • Controllo autonomia</title><style>:root{color-scheme:dark}*{box-sizing:border-box}body{margin:0;background:#07101f;color:#e4f3ff;font:15px system-ui,sans-serif}main{max-width:740px;margin:auto;padding:24px 17px 70px}h1{font-size:25px}h2{font-size:17px;margin:0 0 12px}.muted{color:#9fb9d0}a{color:#89cafe}.card{background:#102138;border:1px solid #294763;border-radius:16px;padding:18px;margin:15px 0}.pill{background:#182e49;border-radius:40px;padding:5px 10px;font-size:12px;white-space:nowrap}.line{display:flex;align-items:center;justify-content:space-between;gap:14px;padding:12px 0;border-top:1px solid #294056}.line:first-child{border-top:0}.good{color:#8ae9bc}.warn{color:#ffce82}.bad{color:#ff8888}p{line-height:1.5}small{font-size:12px;color:#9fb9d0}button{color:#e5f6ff;background:#134974;border:1px solid #5293bd;border-radius:10px;padding:11px 16px;font:inherit}</style></head><body><main><a href=\"/jarvis\">← JARVIS</a><h1>Controllo autonomia</h1><p class=\"muted\">Autodiagnostica ogni sei ore. I controlli distinguono tra verifiche riuscite, anomalie e test non ancora eseguiti. Le approvazioni restano in mano tua.</p><div class=\"card\"><div class=\"line\"><strong>Stato generale</strong><span class=\"pill\" id=\"overall\">Caricamento…</span></div><div class=\"line\"><strong>Ultima verifica</strong><span id=\"last\" class=\"muted\">—</span></div><div class=\"line\"><strong>Test superati</strong><span id=\"count\">—</span></div><div class=\"line\"><strong>Pubblicazione automatica</strong><span class=\"warn\">Disabilitata</span></div></div><section class=\"card\"><h2>Diagnostica dettagliata</h2><div id=\"findings\"><small>Nessun dato disponibile.</small></div></section><section class=\"card\"><h2>Proposte di auto-correzione</h2><p class=\"muted\">Analisi e piani senza modifiche automatiche ai sistemi. Ogni intervento richiede autorizzazione.</p><div id=\"remediations\"><small>Caricamento dei piani…</small></div></section><section class=\"card\"><h2>Decisioni in sospeso</h2><div id=\"approvals\"><small>Verifica in corso…</small></div></section><section class=\"card\"><h2>Ultimi controlli</h2><div id=\"history\"><small>Il registro si compilerà alla prima esecuzione programmata.</small></div></section><button id=\"refresh\" type=\"button\">Aggiorna stato</button><p><small>Questo pannello è di sola lettura: non approva acquisti, non invia comunicazioni, non distribuisce versioni e non modifica i database.</small></p><p><a href=\"/recovery-download-v3\">Archivio cifrato</a> · <a href=\"/staging-control-v3\">Staging</a></p></main><script>const el=id=>document.getElementById(id);function line(label,value,cl=''){const d=document.createElement('div');d.className='line';const a=document.createElement('span'),b=document.createElement('span');a.textContent=label;b.textContent=value;b.className=cl;d.append(a,b);return d}function fmt(v){if(!v)return 'Non ancora eseguito';return String(v).replace('T',' ')+' UTC'}async function render(){el('refresh').disabled=true;try{const response=await fetch('/api/autonomy/status',{cache:'no-store',credentials:'same-origin'});if(!response.ok)throw Error('Stato momentaneamente non disponibile');const data=await response.json();const latest=data.latest;el('overall').textContent=latest?({healthy:'Operativo',attention:'Da verificare',blocked:'Bloccato'}[latest.status]||latest.status):'In attesa del primo controllo';el('overall').className='pill '+(latest?.status==='healthy'?'good':latest?.status==='blocked'?'bad':'warn');el('last').textContent=fmt(latest?.created_at);el('count').textContent=latest?latest.checks_passed+'/'+latest.checks_total:'—';el('findings').replaceChildren();for(const item of latest?.findings||[])el('findings').append(line(item.key.replace(/_/g,' '),item.status==='passed'?'Superato':'Da verificare',item.status==='passed'?'good':'warn'));if(!latest?.findings?.length)el('findings').textContent='Non ci sono ancora diagnostiche programmate.';el('approvals').replaceChildren();for(const item of data.pending_approvals||[])el('approvals').append(line(item.title,item.kind||'Approvazione','warn'));if(!data.pending_approvals?.length)el('approvals').textContent='Nessuna proposta in attesa.';el('history').replaceChildren();for(const item of data.recent_runs||[])el('history').append(line(fmt(item.created_at),item.checks_passed+'/'+item.checks_total+' · '+item.status,item.status==='healthy'?'good':'warn'));if(!data.recent_runs?.length)el('history').textContent='Nessuna esecuzione programmata ancora registrata.'}catch(e){el('overall').textContent='Non disponibile';el('findings').textContent=String(e.message||e)}finally{el('refresh').disabled=false}}el('refresh').addEventListener('click',render);render();async function loadRemediations(){const host=el('remediations');host.replaceChildren();try{const response=await fetch('/api/autonomy/remediations',{credentials:'same-origin',cache:'no-store'});if(!response.ok)throw Error('Registro non disponibile');const data=await response.json();for(const item of data.cases||[]){const wrap=document.createElement('div');wrap.className='line';wrap.style.display='block';const h=document.createElement('strong');h.textContent=item.title;const meta=document.createElement('p');meta.className=item.state==='needs_review'?'warn':'muted';meta.textContent=(item.state==='needs_review'?'Da valutare':item.state==='watching'?'In osservazione':'Risolto')+' · Rischio '+item.risk+' · '+item.detected_count+' rilevazioni';const note=document.createElement('small');note.textContent='Diagnosi: '+item.diagnosis+' — Verifica prevista: '+item.test_plan;wrap.append(h,meta,note);host.append(wrap)}if(!data.cases?.length)host.textContent='Nessuna proposta di correzione registrata.'}catch(e){host.textContent=String(e.message||e)}};const oldRender=render;el('refresh').removeEventListener('click',render);el('refresh').addEventListener('click',async()=>{await oldRender();await loadRemediations()});loadRemediations();</script></body></html>",{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff','Content-Security-Policy':"default-src 'none'; script-src 'unsafe-inline'; style-src 'unsafe-inline'; connect-src 'self'; base-uri 'none'; frame-ancestors 'none'"}});
