 const projectBackup=await env.DB.prepare('SELECT snapshot_id,rows_total,copy_integrity_verified,referential_check_verified,restored_to_isolated_db_verified,restored_rows,full_backup,created_at FROM project_backup_audit ORDER BY created_at DESC LIMIT 1').first();const projectRestoreOk=!!(projectBackup?.copy_integrity_verified===1&&projectBackup?.referential_check_verified===1&&projectBackup?.restored_to_isolated_db_verified===1&&projectBackup?.restored_rows===projectBackup?.rows_total);
