  const recovery=await env.DB.prepare('SELECT production_integrity,staging_integrity,independent_backup_verified,isolated_restore_drill,created_at FROM recovery_preflight_audit ORDER BY created_at DESC LIMIT 1').first();const backupVerified=!!(recovery?.independent_backup_verified===1&&recovery?.production_integrity==='ok'&&recovery?.staging_integrity==='ok'&&recovery?.isolated_restore_drill===1);
