    if(!body||typeof body.project_id!=="string"||!/^[A-Za-z0-9_-]{1,100}$/.test(body.project_id)||Object.keys(body).some(k=>k!=="project_id"))return json({error:"Invalid project request"},400,origin);
    const project=await env.DB.prepare("SELECT id,name FROM projects WHERE id=? AND status='active'").bind(body.project_id).first();if(!project)return json({error:"Active project not found"},404,origin);
