        if(!title||title.length<4)return json({error:"Invalid AI suggestion"},502,origin);
        const existing=(await env.DB.prepare("SELECT id,title FROM tasks WHERE status!='done' AND ((project_id = ?) OR (project_id IS NULL AND ? IS NULL)) LIMIT 200").bind(projectId,projectId).all()).results||[];
        const norm=s=>s.toLocaleLowerCase("it").normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^a-z0-9]+/g," ").trim();
        const match=existing.find(t=>norm(t.title)===norm(title));
        return json({status:"suggested",title,project_id:projectId,project_auto_matched:matchedAutomatically,duplicate_warning:match?{id:match.id,title:match.title}:null,requires_approval:true,saved:false},200,origin);
